using Api.Web.FinanceIA.Models.Financia;

namespace Api.Web.FinanceIA.Models.Entities;

/// <summary>
/// EF Core entity that maps to [dbo].[UserInvitations].
/// Represents a pending invitation sent by an admin to onboard a new user.
/// Records may be updated (UsedAt) — this is NOT an audit table.
/// </summary>
public sealed class UserInvitation
{
    /// <summary>Primary key, generated by the database (NEWID()).</summary>
    public Guid InvitationId { get; set; }

    /// <summary>Tenant that owns this invitation (NVARCHAR(100), e.g. "SgrOneClickSandboxFB2").</summary>
    public string TenantId { get; set; } = string.Empty;

    /// <summary>Email address of the invited user, stored in lowercase.</summary>
    public string Email { get; set; } = string.Empty;

    /// <summary>
    /// Role assigned to the user upon accepting the invitation.
    /// Allowed values: Analyst, RiskManager, Admin, Auditor.
    /// </summary>
    public string Role { get; set; } = string.Empty;

    /// <summary>
    /// UserId of the admin who created the invitation. Null for an invitation issued by the
    /// first-admin bootstrap (POST /api/bff/setup/first-admin), which has no inviter: the tenant
    /// has no admin yet. Nullable since DDL 075.
    /// </summary>
    public Guid? InvitedByUserId { get; set; }

    /// <summary>Unique opaque token sent to the invitee via email.</summary>
    public string Token { get; set; } = string.Empty;

    /// <summary>UTC timestamp after which the invitation is no longer valid.</summary>
    public DateTime ExpiresAt { get; set; }

    /// <summary>UTC timestamp when the invitation was accepted. Null if not yet used.</summary>
    public DateTime? UsedAt { get; set; }

    /// <summary>UTC timestamp when the invitation was created.</summary>
    public DateTime CreatedAt { get; set; }

    /// <summary>
    /// UTC timestamp when an admin revoked the invitation. Null if not revoked.
    /// Distinct from <see cref="UsedAt"/>: revocation cancels a still-pending invite,
    /// whereas UsedAt marks acceptance.
    /// </summary>
    public DateTime? RevokedAt { get; set; }

    /// <summary>
    /// UserId of the admin who revoked the invitation. Null if not revoked — and also when the
    /// first-admin bootstrap replaced its own earlier invitation (<see cref="RevokedAt"/> set).
    /// </summary>
    public Guid? RevokedByUserId { get; set; }

    /// <summary>Navigation property to the admin who created the invitation.</summary>
    public User? InvitedBy { get; set; }
}
